-- SYNTHETIC TEST ONLY.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
GRANT USAGE ON SCHEMA public TO anon,authenticated;
CREATE TABLE public.league_standings(id integer PRIMARY KEY,owner_name text NOT NULL);
INSERT INTO public.league_standings VALUES (1,'one'),(2,'two');
ALTER TABLE public.league_standings ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.league_standings TO anon,authenticated;
CREATE POLICY "Standings: lectura publica" ON public.league_standings AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);
CREATE POLICY "Permitir lectura publica de posiciones" ON public.league_standings AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);
CREATE POLICY "Permitir lectura publica de posiciones de liga" ON public.league_standings AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);
CREATE POLICY qa_write_insert ON public.league_standings FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY qa_write_update ON public.league_standings FOR UPDATE TO authenticated USING (false) WITH CHECK (false);
CREATE POLICY qa_write_delete ON public.league_standings FOR DELETE TO authenticated USING (false);
