CREATE TEMP TABLE qa_before AS SELECT tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND cmd<>'SELECT';
CREATE FUNCTION pg_temp.assert_reads() RETURNS void LANGUAGE plpgsql AS $$
DECLARE t text; n int;
BEGIN
 FOREACH t IN ARRAY ARRAY['league_standings','current_league_champion','league_rooms','leagues','players','site_settings','tournament_results'] LOOP
 EXECUTE format('SELECT count(*) FROM public.%I',t) INTO n;
 IF n<>2 THEN RAISE EXCEPTION 'read mismatch %',t; END IF;
 BEGIN EXECUTE format('INSERT INTO public.%I VALUES (3,''denied'')',t);
 RAISE EXCEPTION 'write unexpectedly allowed %',t;
 EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE format('UPDATE public.%I SET owner_name=''denied''',t);
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>0 THEN RAISE EXCEPTION 'update unexpectedly allowed'; END IF;
 EXECUTE format('DELETE FROM public.%I',t);
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>0 THEN RAISE EXCEPTION 'delete unexpectedly allowed'; END IF;
 END LOOP;
END;$$;
SET ROLE anon;
SELECT pg_temp.assert_reads();
RESET ROLE;
SET ROLE authenticated;
SELECT pg_temp.assert_reads();
RESET ROLE;
\i docs/security/rls-identical-read-policies-2026-11-22.CANDIDATE.sql
DO $$BEGIN
 IF (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND cmd='SELECT')<>7 THEN RAISE EXCEPTION 'unexpected remaining reads'; END IF;
 IF EXISTS((SELECT * FROM qa_before EXCEPT SELECT tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND cmd<>'SELECT') UNION ALL (SELECT tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND cmd<>'SELECT' EXCEPT SELECT * FROM qa_before)) THEN RAISE EXCEPTION 'write policy changed'; END IF;
END$$;
SET ROLE anon;
SELECT pg_temp.assert_reads();
RESET ROLE;
SET ROLE authenticated;
SELECT pg_temp.assert_reads();
RESET ROLE;
\i docs/security/rls-identical-read-policies-2026-11-22.ROLLBACK.sql
DO $$BEGIN IF (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND cmd='SELECT')<>15 THEN RAISE EXCEPTION 'rollback count mismatch'; END IF; END$$;
SET ROLE anon;
SELECT pg_temp.assert_reads();
RESET ROLE;
SET ROLE authenticated;
SELECT pg_temp.assert_reads();
RESET ROLE;
\echo PASS: original and consolidated synthetic roles preserve public reads and deny writes; rollback restores 15 read policies.
